Below is a production-grade core subsystem in engine-agnostic C++20 plus an instanced HLSL wind vertex stage. It uses position-based stem constraints because that family of solvers is fast, stable, and well suited to interactive real-time simulation, and it pushes most visible wind motion into the GPU because that scales cleanly with large instanced vegetation fields.[1][2]

## Core system

The C++ module covers deterministic chunk generation, biome suitability scoring, spatial competition, regrowth, actor-induced trampling impulses, wind sampling, and XPBD-style stem solving for shrubs, grasses, saplings, and trees. The shader then consumes per-instance bend and wind data so the renderer can add low-frequency trunk sway and higher-frequency branch and leaf motion without forcing the CPU to animate every vertex.[3][2][1]

```cpp
// flora_ecosystem.hpp
#pragma once
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <functional>
#include <limits>
#include <span>
#include <string>
#include <utility>
#include <vector>

namespace frontier::flora {

constexpr float kPi = 3.14159265358979323846f;

struct Vec3 {
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    constexpr Vec3() = default;
    constexpr Vec3(float vx, float vy, float vz) : x(vx), y(vy), z(vz) {}

    Vec3 operator+(const Vec3& r) const { return {x + r.x, y + r.y, z + r.z}; }
    Vec3 operator-(const Vec3& r) const { return {x - r.x, y - r.y, z - r.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return {x / s, y / s, z / s}; }
    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
    Vec3& operator-=(const Vec3& r) { x -= r.x; y -= r.y; z -= r.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

inline float Dot(const Vec3& a, const Vec3& b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
inline Vec3 Cross(const Vec3& a, const Vec3& b) {
    return {a.y*b.z - a.z*b.y, a.z*b.x - a.x*b.z, a.x*b.y - a.y*b.x};
}
inline float LengthSq(const Vec3& v) { return Dot(v, v); }
inline float Length(const Vec3& v) { return std::sqrt(LengthSq(v)); }
inline Vec3 Normalize(const Vec3& v) {
    const float len = Length(v);
    return (len > 1e-6f) ? (v / len) : Vec3{0.0f, 1.0f, 0.0f};
}
inline Vec3 Lerp(const Vec3& a, const Vec3& b, float t) { return a * (1.0f - t) + b * t; }
inline float Clamp(float v, float lo, float hi) { return std::max(lo, std::min(v, hi)); }
inline float Saturate(float v) { return Clamp(v, 0.0f, 1.0f); }
inline float SmoothStep(float a, float b, float x) {
    const float t = Saturate((x - a) / (b - a));
    return t * t * (3.0f - 2.0f * t);
}

inline uint64_t SplitMix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

inline uint64_t Hash4(uint64_t a, uint64_t b, uint64_t c, uint64_t d) {
    uint64_t h = 0x9e3779b97f4a7c15ULL;
    h ^= SplitMix64(a + 0x100000001b3ULL);
    h ^= SplitMix64(b + 0x100000001b5ULL);
    h ^= SplitMix64(c + 0x100000001b7ULL);
    h ^= SplitMix64(d + 0x100000001b9ULL);
    return SplitMix64(h);
}

inline float Hash01(uint64_t seed) {
    constexpr double inv = 1.0 / static_cast<double>(std::numeric_limits<uint64_t>::max());
    return static_cast<float>(static_cast<double>(SplitMix64(seed)) * inv);
}

inline float Lerp(float a, float b, float t) { return a * (1.0f - t) + b * t; }

inline float ValueNoise2D(float x, float z, uint64_t seed) {
    const int ix = static_cast<int>(std::floor(x));
    const int iz = static_cast<int>(std::floor(z));
    const float fx = x - static_cast<float>(ix);
    const float fz = z - static_cast<float>(iz);

    const auto n = [&](int px, int pz) {
        return Hash01(Hash4(seed, static_cast<uint64_t>(px), static_cast<uint64_t>(pz), 0));
    };

    const float u = fx * fx * (3.0f - 2.0f * fx);
    const float v = fz * fz * (3.0f - 2.0f * fz);

    const float a = n(ix, iz);
    const float b = n(ix + 1, iz);
    const float c = n(ix, iz + 1);
    const float d = n(ix + 1, iz + 1);

    return Lerp(Lerp(a, b, u), Lerp(c, d, u), v);
}

inline float FBM2D(float x, float z, uint64_t seed, int octaves = 4) {
    float amp = 0.5f;
    float freq = 1.0f;
    float sum = 0.0f;
    float norm = 0.0f;
    for (int i = 0; i < octaves; ++i) {
        sum += ValueNoise2D(x * freq, z * freq, seed + static_cast<uint64_t>(i) * 7919ULL) * amp;
        norm += amp;
        amp *= 0.5f;
        freq *= 2.01f;
    }
    return (norm > 0.0f) ? (sum / norm) : 0.0f;
}

struct EnvironmentSample {
    float height = 0.0f;
    float slope = 0.0f;
    float moisture = 0.5f;
    float temperature = 0.5f;
    float nutrients = 0.5f;
    float light = 0.8f;
    float disturbance = 0.0f;
};

struct SpeciesProfile {
    std::string name;

    float density = 0.25f;
    float minSpacing = 0.75f;
    float maxSlope = 0.85f;

    float preferredMoisture = 0.5f;
    float moistureTolerance = 0.3f;
    float preferredTemperature = 0.5f;
    float temperatureTolerance = 0.3f;
    float preferredLight = 0.7f;
    float lightTolerance = 0.4f;
    float preferredNutrients = 0.5f;
    float nutrientTolerance = 0.4f;
    float disturbanceAffinity = 0.2f;
    float shadeTolerance = 0.25f;

    float minScale = 0.8f;
    float maxScale = 1.2f;
    float stemHeight = 1.5f;
    int segmentCount = 6;

    float mass = 1.0f;
    float stiffness = 1200.0f;
    float damping = 0.08f;
    float windDrag = 0.9f;
    float actorBendSensitivity = 1.0f;
    float recoveryRate = 0.2f;
    float canopyRadius = 1.25f;
    float canopyHeightFactor = 0.9f;

    std::array<float, 3> albedo = {0.35f, 0.55f, 0.22f};
};

struct WindSettings {
    Vec3 direction = Normalize(Vec3{1.0f, 0.0f, 0.25f});
    float baseSpeed = 4.5f;
    float gustSpeed = 2.0f;
    float gustFrequency = 0.07f;
    float turbulence = 1.0f;
};

struct ChunkSettings {
    uint64_t worldSeed = 1;
    float chunkSize = 128.0f;
    float cellSize = 2.0f;
    float jitter = 0.75f;
    int solverIterations = 8;
};

struct ActorInfluence {
    Vec3 position;
    Vec3 velocity;
    float radius = 1.0f;
    float strength = 1.0f;
};

struct StemParticle {
    Vec3 pos;
    Vec3 prev;
    float invMass = 1.0f;
};

struct StemConstraint {
    uint16_t a = 0;
    uint16_t b = 0;
    float restLength = 0.0f;
    float compliance = 0.0f;
    float lambda = 0.0f;
};

struct FloraInstance {
    uint32_t id = 0;
    uint16_t species = 0;
    Vec3 rootPos;
    float yaw = 0.0f;
    float scale = 1.0f;
    float age = 0.5f;
    float health = 1.0f;
    float vigor = 1.0f;
    float shade = 0.0f;
    bool alive = true;

    std::vector<StemParticle> particles;
    std::vector<StemConstraint> constraints;
    Vec3 bendWS;
};

struct GpuFloraInstance {
    float model[16];
    float bendWS[4];
    float params[4];
    float color[4];
};

class ProceduralFloraEcosystem {
public:
    explicit ProceduralFloraEcosystem(ChunkSettings settings = {}, WindSettings wind = {})
        : settings_(settings), wind_(wind) {}

    uint16_t RegisterSpecies(const SpeciesProfile& profile) {
        species_.push_back(profile);
        return static_cast<uint16_t>(species_.size() - 1);
    }

    void Clear() { plants_.clear(); }

    void GenerateChunk(
        int chunkX,
        int chunkZ,
        const std::function<EnvironmentSample(float, float)>& sampleEnvironment)
    {
        const int cells = std::max(1, static_cast<int>(std::floor(settings_.chunkSize / settings_.cellSize)));
        const float originX = chunkX * settings_.chunkSize;
        const float originZ = chunkZ * settings_.chunkSize;

        for (int cz = 0; cz < cells; ++cz) {
            for (int cx = 0; cx < cells; ++cx) {
                const uint64_t cellSeed = Hash4(
                    settings_.worldSeed,
                    static_cast<uint64_t>(chunkX * 73856093 ^ cx),
                    static_cast<uint64_t>(chunkZ * 19349663 ^ cz),
                    0xC0FFEEULL);

                const float jitterX = (Hash01(cellSeed + 11) * 2.0f - 1.0f) * settings_.cellSize * settings_.jitter * 0.5f;
                const float jitterZ = (Hash01(cellSeed + 29) * 2.0f - 1.0f) * settings_.cellSize * settings_.jitter * 0.5f;

                const float wx = originX + (static_cast<float>(cx) + 0.5f) * settings_.cellSize + jitterX;
                const float wz = originZ + (static_cast<float>(cz) + 0.5f) * settings_.cellSize + jitterZ;
                const EnvironmentSample env = sampleEnvironment(wx, wz);

                int chosen = -1;
                float chosenScore = 0.0f;

                for (uint16_t s = 0; s < species_.size(); ++s) {
                    const float suitability = SpeciesSuitability(species_[s], env, wx, wz);
                    if (suitability <= 0.0f) continue;

                    const float roll = Hash01(cellSeed + s * 977ULL);
                    const float score = suitability * (0.6f + 0.4f * roll);
                    if (score > chosenScore && roll < species_[s].density) {
                        chosenScore = score;
                        chosen = static_cast<int>(s);
                    }
                }

                if (chosen < 0) continue;
                const SpeciesProfile& sp = species_[static_cast<size_t>(chosen)];
                if (env.slope > sp.maxSlope) continue;
                if (OverlapsExisting(wx, wz, sp.minSpacing)) continue;

                FloraInstance plant;
                plant.id = nextId_++;
                plant.species = static_cast<uint16_t>(chosen);
                plant.rootPos = Vec3{wx, env.height, wz};
                plant.yaw = Hash01(cellSeed + 101) * 2.0f * kPi;
                plant.scale = Lerp(sp.minScale, sp.maxScale, Hash01(cellSeed + 313));
                plant.age = Hash01(cellSeed + 509);
                plant.health = 0.8f + 0.2f * Hash01(cellSeed + 911);
                plant.vigor = 0.6f + 0.4f * chosenScore;
                BuildStem(plant, sp);
                plants_.push_back(std::move(plant));
            }
        }

        ComputeShadeCompetition();
    }

    void Simulate(float dt, float time, std::span<const ActorInfluence> actors) {
        if (dt <= 0.0f) return;
        const float clampedDt = Clamp(dt, 1.0f / 240.0f, 1.0f / 20.0f);
        const float dt2 = clampedDt * clampedDt;

        for (FloraInstance& plant : plants_) {
            if (!plant.alive) continue;
            const SpeciesProfile& sp = species_[plant.species];

            for (StemConstraint& c : plant.constraints) c.lambda = 0.0f;
            if (plant.particles.empty()) continue;

            plant.particles[0].pos = plant.rootPos;
            plant.particles[0].prev = plant.rootPos;

            const float healthRecovery = sp.recoveryRate * clampedDt * (1.0f - plant.shade * (1.0f - sp.shadeTolerance));
            plant.health = Saturate(plant.health + healthRecovery * 0.1f);

            for (size_t i = 1; i < plant.particles.size(); ++i) {
                StemParticle& p = plant.particles[i];
                const Vec3 velocity = (p.pos - p.prev) * (1.0f - sp.damping);
                p.prev = p.pos;

                const float height01 = static_cast<float>(i) / static_cast<float>(plant.particles.size() - 1);
                const Vec3 wind = SampleWind(p.pos, time);
                const Vec3 gravity = Vec3{0.0f, -9.81f, 0.0f} * 0.08f;
                Vec3 accel = wind * (sp.windDrag * height01 * plant.vigor) + gravity;

                for (const ActorInfluence& actor : actors) {
                    const Vec3 delta = p.pos - actor.position;
                    const float d2 = LengthSq(delta);
                    const float r = actor.radius + 0.2f;
                    if (d2 < r * r) {
                        const float d = std::sqrt(std::max(d2, 1e-6f));
                        const Vec3 away = delta / d;
                        const float falloff = 1.0f - d / r;
                        accel += away * (actor.strength * sp.actorBendSensitivity * falloff * 28.0f);
                        accel += actor.velocity * (0.08f * falloff);
                        plant.health = Saturate(plant.health - clampedDt * falloff * 0.2f);
                    }
                }

                p.pos += velocity + accel * dt2;
            }

            for (int iter = 0; iter < settings_.solverIterations; ++iter) {
                SolveStemConstraintsXPBD(plant, clampedDt);
                SolveUprightBias(plant, sp, 0.06f * sp.stiffness * 0.001f);
                plant.particles[0].pos = plant.rootPos;
            }

            const Vec3 top = plant.particles.back().pos;
            const Vec3 offset = top - plant.rootPos;
            plant.bendWS = Vec3{offset.x, 0.0f, offset.z};
        }
    }

    const std::vector<FloraInstance>& Plants() const { return plants_; }

    std::vector<GpuFloraInstance> BuildGpuInstances() const {
        std::vector<GpuFloraInstance> out;
        out.reserve(plants_.size());

        for (const FloraInstance& plant : plants_) {
            if (!plant.alive) continue;
            const SpeciesProfile& sp = species_[plant.species];

            const float c = std::cos(plant.yaw);
            const float s = std::sin(plant.yaw);
            const float scale = plant.scale;

            GpuFloraInstance gpu{};
            gpu.model[0]  =  c * scale; gpu.model[1]  = 0.0f; gpu.model[2]  = -s * scale; gpu.model[3]  = 0.0f;
            gpu.model[4]  = 0.0f;       gpu.model[5]  = scale; gpu.model[6]  = 0.0f;       gpu.model[7]  = 0.0f;
            gpu.model[8]  =  s * scale; gpu.model[9]  = 0.0f; gpu.model[10] =  c * scale; gpu.model[11] = 0.0f;
            gpu.model[12] = plant.rootPos.x;
            gpu.model[13] = plant.rootPos.y;
            gpu.model[14] = plant.rootPos.z;
            gpu.model[15] = 1.0f;

            gpu.bendWS[0] = plant.bendWS.x;
            gpu.bendWS[1] = plant.bendWS.y;
            gpu.bendWS[2] = plant.bendWS.z;
            gpu.bendWS[3] = plant.health;

            gpu.params[0] = static_cast<float>(plant.species);
            gpu.params[1] = plant.vigor;
            gpu.params[2] = plant.shade;
            gpu.params[3] = sp.stemHeight * plant.scale;

            gpu.color[0] = sp.albedo[0];
            gpu.color[1] = sp.albedo[1];
            gpu.color[2] = sp.albedo[2];
            gpu.color[3] = 1.0f;

            out.push_back(gpu);
        }

        return out;
    }

    WindSettings& Wind() { return wind_; }
    const WindSettings& Wind() const { return wind_; }

private:
    std::vector<SpeciesProfile> species_;
    std::vector<FloraInstance> plants_;
    ChunkSettings settings_;
    WindSettings wind_;
    uint32_t nextId_ = 1;

    static float Bell(float x, float center, float tolerance) {
        const float t = std::max(tolerance, 1e-3f);
        const float d = (x - center) / t;
        return std::exp(-d * d * 2.0f);
    }

    float SpeciesSuitability(const SpeciesProfile& sp, const EnvironmentSample& env, float wx, float wz) const {
        const float moisture = Bell(env.moisture, sp.preferredMoisture, sp.moistureTolerance);
        const float temp = Bell(env.temperature, sp.preferredTemperature, sp.temperatureTolerance);
        const float light = Bell(env.light, sp.preferredLight, sp.lightTolerance);
        const float nutrients = Bell(env.nutrients, sp.preferredNutrients, sp.nutrientTolerance);
        const float slope = 1.0f - SmoothStep(sp.maxSlope * 0.6f, sp.maxSlope, env.slope);

        const float disturbanceBias = 1.0f - std::abs(env.disturbance - sp.disturbanceAffinity);
        const float patchNoise = 0.65f + 0.35f * FBM2D(wx * 0.02f, wz * 0.02f, settings_.worldSeed + sp.segmentCount);

        return Saturate(moisture * temp * light * nutrients * slope * Saturate(disturbanceBias) * patchNoise);
    }

    bool OverlapsExisting(float x, float z, float minSpacing) const {
        const Vec3 p{x, 0.0f, z};
        const float minDistSq = minSpacing * minSpacing;
        for (const FloraInstance& plant : plants_) {
            const Vec3 q{plant.rootPos.x, 0.0f, plant.rootPos.z};
            if (LengthSq(p - q) < minDistSq) return true;
        }
        return false;
    }

    void BuildStem(FloraInstance& plant, const SpeciesProfile& sp) {
        const int count = std::max(2, sp.segmentCount + 1);
        plant.particles.resize(static_cast<size_t>(count));
        plant.constraints.clear();
        plant.constraints.reserve(static_cast<size_t>(count * 2));

        const float segmentLength = (sp.stemHeight * plant.scale) / static_cast<float>(count - 1);
        for (int i = 0; i < count; ++i) {
            const Vec3 p = plant.rootPos + Vec3{0.0f, segmentLength * static_cast<float>(i), 0.0f};
            plant.particles[static_cast<size_t>(i)] = StemParticle{
                p, p, (i == 0) ? 0.0f : (1.0f / std::max(0.01f, sp.mass * (1.0f + i * 0.2f)))
            };
        }

        const float compliance = 1.0f / std::max(1.0f, sp.stiffness);
        for (int i = 0; i < count - 1; ++i) {
            plant.constraints.push_back(StemConstraint{
                static_cast<uint16_t>(i),
                static_cast<uint16_t>(i + 1),
                segmentLength,
                compliance,
                0.0f
            });
        }

        for (int i = 0; i < count - 2; ++i) {
            plant.constraints.push_back(StemConstraint{
                static_cast<uint16_t>(i),
                static_cast<uint16_t>(i + 2),
                segmentLength * 2.0f,
                compliance * 0.5f,
                0.0f
            });
        }
    }

    Vec3 SampleWind(const Vec3& p, float time) const {
        const Vec3 dir = Normalize(wind_.direction);
        const float gust =
            std::sin(time * wind_.gustFrequency + p.x * 0.03f + p.z * 0.025f) * 0.5f +
            std::sin(time * wind_.gustFrequency * 1.77f + p.x * 0.011f - p.z * 0.019f) * 0.3f;

        const float swirlX = FBM2D(p.x * 0.03f + time * 0.05f, p.z * 0.03f, settings_.worldSeed + 1001) - 0.5f;
        const float swirlZ = FBM2D(p.z * 0.03f - time * 0.04f, p.x * 0.03f, settings_.worldSeed + 2003) - 0.5f;

        const Vec3 turbulence = Normalize(Vec3{swirlX, 0.0f, swirlZ});
        const float speed = wind_.baseSpeed + gust * wind_.gustSpeed;
        return (dir * speed + turbulence * wind_.turbulence) * 0.9f;
    }

    void SolveStemConstraintsXPBD(FloraInstance& plant, float dt) {
        const float invDt2 = 1.0f / std::max(1e-6f, dt * dt);

        for (StemConstraint& c : plant.constraints) {
            StemParticle& a = plant.particles[c.a];
            StemParticle& b = plant.particles[c.b];

            const Vec3 delta = b.pos - a.pos;
            const float len = Length(delta);
            if (len < 1e-6f) continue;

            const Vec3 n = delta / len;
            const float C = len - c.restLength;
            const float w = a.invMass + b.invMass;
            if (w <= 0.0f) continue;

            const float alpha = c.compliance * invDt2;
            const float dlambda = (-C - alpha * c.lambda) / (w + alpha);
            c.lambda += dlambda;

            a.pos -= n * (dlambda * a.invMass);
            b.pos += n * (dlambda * b.invMass);
        }
    }

    void SolveUprightBias(FloraInstance& plant, const SpeciesProfile& sp, float strength) {
        if (plant.particles.size() < 2) return;
        const float totalHeight = sp.stemHeight * plant.scale;
        for (size_t i = 1; i < plant.particles.size(); ++i) {
            const float t = static_cast<float>(i) / static_cast<float>(plant.particles.size() - 1);
            const Vec3 target = plant.rootPos + Vec3{0.0f, totalHeight * t, 0.0f};
            plant.particles[i].pos = Lerp(plant.particles[i].pos, target, strength * (1.0f - t * 0.35f));
        }
    }

    void ComputeShadeCompetition() {
        for (FloraInstance& a : plants_) a.shade = 0.0f;

        for (size_t i = 0; i < plants_.size(); ++i) {
            FloraInstance& a = plants_[i];
            const SpeciesProfile& sa = species_[a.species];
            const float aHeight = sa.stemHeight * a.scale;

            for (size_t j = 0; j < plants_.size(); ++j) {
                if (i == j) continue;
                const FloraInstance& b = plants_[j];
                const SpeciesProfile& sb = species_[b.species];
                const float bHeight = sb.stemHeight * b.scale;
                if (bHeight <= aHeight) continue;

                const float radius = sb.canopyRadius * b.scale;
                const Vec3 d = a.rootPos - b.rootPos;
                const float planar = std::sqrt(d.x*d.x + d.z*d.z);
                if (planar > radius) continue;

                const float heightCover = Saturate((bHeight * sb.canopyHeightFactor - a.rootPos.y) / std::max(0.1f, bHeight));
                const float radialFalloff = 1.0f - planar / std::max(radius, 1e-3f);
                a.shade = Saturate(a.shade + radialFalloff * heightCover * 0.35f);
            }

            a.vigor *= (1.0f - a.shade * (1.0f - sa.shadeTolerance));
            a.vigor = Clamp(a.vigor, 0.2f, 1.5f);
        }
    }
};

} // namespace frontier::flora
```

## GPU wind

This shader follows the real-time vegetation pattern where large-scale motion is treated as low-frequency trunk bending and fine motion is layered as branch and leaf detail, which is one of the main reasons procedural wind remains compatible with instancing at scale.[2][3]

```hlsl
// vegetation_wind_instanced.hlsl
cbuffer FloraGlobals : register(b0)
{
    float4x4 ViewProj;
    float3 GlobalWindDir;
    float Time;
    float GlobalWindSpeed;
    float GustAmplitude;
    float BranchAmplitude;
    float LeafAmplitude;
    float TurbulenceScale;
    float TurbulenceSpeed;
    float Padding0;
};

struct VSInput
{
    float3 positionOS : POSITION;
    float3 normalOS   : NORMAL;
    float2 uv         : TEXCOORD0;
    float4 color      : COLOR0;     // R = leaf flutter mask, G = phase, B = branch stiffness mask, A = height mask override
    uint instanceId   : SV_InstanceID;
};

struct FloraInstanceData
{
    float4 row0;
    float4 row1;
    float4 row2;
    float4 row3;
    float4 bendWS;   // xyz = cpu bend, w = health
    float4 params;   // x = species, y = vigor, z = shade, w = plant height
    float4 albedo;
};

StructuredBuffer<FloraInstanceData> FloraInstances : register(t0);

struct VSOutput
{
    float4 positionCS : SV_POSITION;
    float3 normalWS   : TEXCOORD0;
    float2 uv         : TEXCOORD1;
    float4 color      : TEXCOORD2;
};

float Hash11(float p)
{
    p = frac(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return frac(p);
}

float Noise2(float2 p)
{
    float2 i = floor(p);
    float2 f = frac(p);
    float a = Hash11(i.x + i.y * 57.0);
    float b = Hash11(i.x + 1.0 + i.y * 57.0);
    float c = Hash11(i.x + (i.y + 1.0) * 57.0);
    float d = Hash11(i.x + 1.0 + (i.y + 1.0) * 57.0);
    float2 u = f * f * (3.0 - 2.0 * f);
    return lerp(lerp(a, b, u.x), lerp(c, d, u.x), u.y);
}

float3x3 InstanceBasis(FloraInstanceData inst)
{
    return float3x3(
        inst.row0.xyz,
        inst.row1.xyz,
        inst.row2.xyz
    );
}

float3 InstanceTranslation(FloraInstanceData inst)
{
    return float3(inst.row0.w, inst.row1.w, inst.row2.w);
}

float3 MulPoint(float3 p, FloraInstanceData inst)
{
    return mul(InstanceBasis(inst), p) + InstanceTranslation(inst);
}

float3 MulVector(float3 v, FloraInstanceData inst)
{
    return mul(InstanceBasis(inst), v);
}

VSOutput main(VSInput input)
{
    FloraInstanceData inst = FloraInstances[input.instanceId];
    VSOutput o;

    float plantHeight = max(inst.params.w, 0.01);
    float localHeight01 = saturate((input.positionOS.y / plantHeight));
    float phase = input.color.g * 6.2831853 + Hash11((float)input.instanceId) * 6.2831853;
    float stiffnessMask = saturate(input.color.b);
    float leafMask = saturate(input.color.r);

    float3 posWS = MulPoint(input.positionOS, inst);
    float3 normalWS = normalize(MulVector(input.normalOS, inst));

    float2 fieldUV = posWS.xz * TurbulenceScale + Time * TurbulenceSpeed;
    float noiseA = Noise2(fieldUV);
    float noiseB = Noise2(fieldUV.yx * 1.73 + 13.7);

    float gust = sin(Time * 0.8 + phase + noiseA * 2.0) * 0.5 + 0.5;
    float3 windDir = normalize(GlobalWindDir + float3(noiseA - 0.5, 0.0, noiseB - 0.5) * 0.35);
    float3 trunkOffset = windDir * (GlobalWindSpeed * 0.02 + GustAmplitude * gust * 0.035);
    trunkOffset *= localHeight01 * localHeight01 * inst.params.y;

    float branchWave =
        sin(Time * 2.6 + phase + localHeight01 * 4.5) * 0.5 +
        sin(Time * 1.7 - phase * 1.3 + noiseB * 3.1) * 0.5;

    float leafWave =
        sin(Time * 7.5 + phase * 2.0 + posWS.x * 0.6 + posWS.z * 0.7) * 0.5 +
        sin(Time * 5.2 - phase + posWS.x * 0.9) * 0.5;

    float branchStrength = BranchAmplitude * localHeight01 * (1.0 - stiffnessMask);
    float leafStrength = LeafAmplitude * leafMask;

    float3 cpuBend = inst.bendWS.xyz * (0.25 + 0.75 * localHeight01);
    float3 gpuBend = windDir * branchWave * branchStrength + normalWS * leafWave * leafStrength * 0.15;

    posWS += trunkOffset + cpuBend + gpuBend;
    normalWS = normalize(normalWS + gpuBend * 0.5);

    o.positionCS = mul(ViewProj, float4(posWS, 1.0));
    o.normalWS = normalWS;
    o.uv = input.uv;
    o.color = inst.albedo;
    return o;
}
```

## Example setup

The branch geometry side can be authored with modular branch instancing or an L-system-style generator, both of which are widely used for plant structure synthesis and scale well when many leaves or branches are drawn via instancing.[4][5][6]

